`default_nettype none

// Programmable protocol emulator: a tiny cycle-exact CPU running firmware from ROM, or from a
// 256-word program memory that the host loads over the pins after fabrication.
//   Input pins  0-7  = ui_in[7:0]
//   Input pins  8-15 = uio_in[7:0]
//   Output pins 0-7  = uo_out[7:0]          (push-pull)
//   Open-drain  0-7  = uio[7:0]             (ODRV/ODRVC pull low, otherwise released)
// The firmware in rom.v is generated by tools/asm.py from firmware/*.asm.
//
// Loading a program (see docs/loading.md): raise uio[5] (LOAD), then for every byte put it on
// ui[7:0] and pulse uio[4] (STROBE) high and low, low byte of each 16-bit word first. Lower LOAD
// when done and the CPU starts at address 0 of the loaded program. While LOAD is high the CPU is
// held in reset. Without LOAD after reset the CPU runs the built-in ROM firmware.
module tt_um_atlasmountainz_protocol_emulator (
    input  wire [7:0] ui_in,    // Dedicated inputs
    output wire [7:0] uo_out,   // Dedicated outputs
    input  wire [7:0] uio_in,   // IOs: Input path
    output wire [7:0] uio_out,  // IOs: Output path
    output wire [7:0] uio_oe,   // IOs: Enable path (active high: 0=input, 1=output)
    input  wire       ena,      // always 1 when the design is powered, so you can ignore it
    input  wire       clk,      // clock
    input  wire       rst_n     // reset_n - low to reset
);

  // Two-flop synchroniser: the pins are asynchronous to the core clock.
  reg [15:0] sync1, sync2;
  always @(posedge clk) begin
    if (!rst_n) begin
      sync1 <= 16'd0;
      sync2 <= 16'd0;
    end else begin
      sync1 <= {uio_in, ui_in};
      sync2 <= sync1;
    end
  end

  wire [7:0]  rom_addr;
  wire [127:0] rom_addr_rep;
  wire [15:0] rom_data;
  wire [15:0] ram_data;
  wire [7:0]  od_pull;

  // ---- Program loader --------------------------------------------------------------------
  wire       load_en = sync2[13];   // uio[5]
  wire       strobe  = sync2[12];   // uio[4]
  wire [7:0] ld_byte = sync2[7:0];  // ui[7:0]

  reg        strobe_d;
  reg  [8:0] ld_ptr;                // byte index: bit 0 selects low/high byte
  reg  [7:0] ld_lo;
  reg        use_ram;               // set once LOAD has been seen since reset

  wire wr_pulse = load_en & strobe & ~strobe_d;   // one pulse per STROBE rising edge
  wire ram_we   = wr_pulse & ld_ptr[0];

  always @(posedge clk) begin
    if (!rst_n) begin
      strobe_d <= 1'b0;
      ld_ptr   <= 9'd0;
      ld_lo    <= 8'd0;
      use_ram  <= 1'b0;
    end else begin
      strobe_d <= strobe;
      if (load_en) use_ram <= 1'b1;
      if (!load_en) ld_ptr <= 9'd0;
      else if (wr_pulse) begin
        ld_ptr <= ld_ptr + 9'd1;
        if (!ld_ptr[0]) ld_lo <= ld_byte;
      end
    end
  end

  pmem u_pmem (
      .clk  (clk),
      .we   (ram_we),
      .waddr(ld_ptr[8:1]),
      .wdata({ld_byte, ld_lo}),
      .raddr(rom_addr),
      .raddr_rep(rom_addr_rep),
      .rdata(ram_data)
  );

  wire [15:0] instr = use_ram ? ram_data : rom_data;

  cpu u_cpu (
      .clk     (clk),
      .rst_n   (rst_n & ~load_en),
      .pins_in (sync2),
      .pins_out(uo_out),
      .od_pull (od_pull),
      .rom_addr(rom_addr),
      .rom_addr_rep(rom_addr_rep),
      .rom_data(instr)
  );

  rom u_rom (
      .addr(rom_addr),
      .data(rom_data)
  );

  // Open-drain bidirectional pins (uio): the output value is always 0, and the output
  // enable pulls the line low. Released pins float high via the external pull-up and can
  // still be read as inputs.
  assign uio_out = 8'b0;
  assign uio_oe  = od_pull;

  // List all unused inputs to prevent warnings
  wire _unused = &{ena, 1'b0};

endmodule
